// Angular service (browser)
@Injectable({ providedIn: 'root' })
export class CourseService {
  private http = inject(HttpClient);
  list(page: number) {
    return this.http.get<Course[]>('/api/courses', { params: { page } });
  }
}

// Express route (Node.js server)
app.get('/api/courses', async (req, res) => {
  const page = Number(req.query.page ?? 1);
  const courses = await Course.find().skip((page - 1) * 10).limit(10).lean();
  res.status(200).json(courses);
});

function createCounter(start = 0) {
  let count = start;          // captured by the closures below
  return {
    increment: () => ++count,
    current: () => count,
  };
}

const a = createCounter();
const b = createCounter(10);
a.increment();
a.increment();
console.log(a.current()); // 2
console.log(b.current()); // 10
console.log(a.count);     // undefined: count is private

const enrolments = [
  { student: 'Asha', course: 'MEAN', fee: 25000, active: true, aadhaar: 'XXXX' },
  { student: 'Ravi', course: 'MEAN', active: true, aadhaar: 'YYYY' },
  { student: 'Meera', course: 'Java', fee: 18000, active: false, aadhaar: 'ZZZZ' },
];

const safe = enrolments
  .filter(e => e.active)
  .map(({ aadhaar, fee = 0, ...rest }) => ({ ...rest, fee }));

const total = safe.reduce((sum, { fee }) => sum + fee, 0);
const byCourse = Object.groupBy(safe, e => e.course);

console.log(safe.length, total, Object.keys(byCourse)); // 2 25000 [ 'MEAN' ]

console.log('1: script start');

setTimeout(() => console.log('4: timeout'), 0);

Promise.resolve()
  .then(() => console.log('3: promise'));

console.log('2: script end');

